INSERT INTO kviz_pitanja (tema, tezina, pitanje, odgovor_a, odgovor_b, odgovor_c, odgovor_d, tacan, objasnjenje) VALUES
('Prijava', 'lako', 'Čime se student prijavljuje u Digitalnu menzu?', 'Brojem studentske kartice i lozinkom', 'Brojem indeksa i JMBG-om', 'Email adresom i kodom iz SMS poruke', 'Korisničkim imenom sa fakulteta', 'a', 'Broj kartice ima 12 cifara i odštampan je ispod čipa, a lozinku student dobija na šalteru Studentskog centra.'),
('Prijava', 'srednje', 'Šta aplikacija prikaže kada je broj kartice tačan, a lozinka pogrešna?', '„Pogrešna lozinka.“', '„Kartica ne postoji.“', '„Pogrešan broj kartice ili lozinka.“', 'Ništa, stranica se samo osveži', 'c', 'Poruka je ista i za nepostojeću karticu i za pogrešnu lozinku, da napadač ne bi mogao da sazna koji brojevi kartica postoje.'),
('Prijava', 'lako', 'Šta se dešava kada student pokuša da se prijavi blokiranom karticom?', 'Prijava uspe, ali ne može ništa da kupi', 'Kartica se automatski odblokira', 'Prijava se odbija uz poruku da se javi na šalter Studentskog centra', 'Na email mu stiže nova lozinka', 'c', 'Blokirana kartica ne može da se koristi za prijavu, a kasa i kupovina je takođe odbijaju.'),
('Prijava', 'tesko', 'Čemu služi skriveno polje csrf_token u svakoj formi aplikacije?', 'Sprečava da tuđi sajt pošalje formu u ime prijavljenog korisnika', 'Pamti izabrani jezik stranice', 'Ubrzava učitavanje stranice', 'Čuva lozinku u pregledaču', 'a', 'Token je nasumičan niz koji se čuva u sesiji. Tuđi sajt ga ne zna, pa server odbija formu koja ga nema.'),
('Prijava', 'tesko', 'Kako se lozinke čuvaju u bazi podataka?', 'Kao običan tekst', 'Šifrovane, pa administrator može da ih pročita', 'Ne čuvaju se, proverava ih banka', 'Kao heš (password_hash), a pri prijavi se proveravaju funkcijom password_verify', 'd', 'Iz heša ne može da se vrati prava lozinka, pa ni neko ko vidi bazu ne zna lozinke studenata.'),
('Dopuna kartice', 'lako', 'Koja dva načina dopune kartice nudi aplikacija?', 'Gotovinu na kasi menze i ček', 'PayPal i kriptovalute', 'Platnu karticu i IPS QR kod', 'Samo uplatnicu u pošti', 'c', 'Platnom karticom novac stiže odmah, a IPS QR kod se skenira aplikacijom banke na telefonu.'),
('Dopuna kartice', 'srednje', 'Koliki je najmanji, a koliki najveći iznos jedne dopune?', '100 i 20.000 RSD', '50 i 10.000 RSD', '500 i 5.000 RSD', '1 i 100.000 RSD', 'a', 'Ponuđeni iznosi su od 500 do 5.000 RSD, a kao „Drugi iznos“ može da se upiše ceo broj dinara od 100 do 20.000.'),
('Dopuna kartice', 'srednje', 'Šta se upisuje u „poziv na broj“ kod IPS uplate?', 'Broj indeksa', 'Broj studentske kartice', 'JMBG studenta', 'Broj računa Studentskog centra', 'b', 'Po pozivu na broj Studentski centar zna na čiju karticu treba da doda uplaćeni novac.'),
('Dopuna kartice', 'srednje', 'Kada novac uplaćen preko IPS QR koda stiže na karticu?', 'Čim se otvori stranica sa QR kodom', 'Kada administrator potvrdi uplatu, a do tada ona čeka potvrdu', 'Prvog dana sledećeg meseca', 'Kada student prvi put ode u menzu', 'b', 'IPS uplata se upisuje sa statusom „Čeka potvrdu“ i stanje se ne menja. Administrator je potvrđuje ili odbija na stranici Uplate.'),
('Dopuna kartice', 'lako', 'Šta se dešava pri dopuni test karticom 4000 0000 0000 0002?', 'Plaćanje prolazi', 'Banka odbija plaćanje i stanje kartice se ne menja', 'Studentska kartica se blokira', 'Na karticu se uplati dupli iznos', 'b', 'To je test kartica za odbijeno plaćanje. Sa karticom 4242 4242 4242 4242 plaćanje prolazi.'),
('Dopuna kartice', 'tesko', 'Šta aplikacija pamti od platne kartice kojom je plaćena dopuna?', 'Samo poslednje 4 cifre, u opisu transakcije', 'Ceo broj, datum isteka i CVC', 'Ceo broj kartice', 'Ime vlasnika i CVC', 'a', 'Podaci platne kartice se ne čuvaju. Broj kartice i CVC se ne vraćaju ni u formu posle greške.'),
('Dopuna kartice', 'tesko', 'Kako aplikacija prepozna pogrešno ukucan broj platne kartice pre slanja banci?', 'Pita banku da li kartica postoji', 'Proverava samo da li broj počinje cifrom 4', 'Luhn proverom kontrolne cifre', 'Ne proverava, to radi samo banka', 'c', 'Svi brojevi platnih kartica imaju kontrolnu cifru, pa Luhn provera hvata većinu grešaka u kucanju, npr. jednu pogrešnu cifru.'),
('Kupovina obroka', 'lako', 'Za koje mesece student može da kupi obroke?', 'Za bilo koji mesec u godini', 'Za tekući i sledeći mesec', 'Samo za tekući mesec', 'Samo za ceo semestar odjednom', 'b', 'Na stranici Kupovina obroka biraju se dva meseca: tekući i sledeći. Kupljeni obroci važe do kraja izabranog meseca.'),
('Kupovina obroka', 'lako', 'Koliko obroka iste vrste student može da dobije u jednom danu?', 'Neograničeno, dok ima obroka', 'Najviše jedan', 'Najviše dva', 'Tri, ako ima novca na kartici', 'b', 'Pravilo važi za sve menze zajedno: jedan doručak, jedan ručak i jedna večera dnevno.'),
('Kupovina obroka', 'srednje', 'Šta se dešava sa već kupljenim obrocima kada administrator promeni cene?', 'Student doplaćuje razliku', 'Studentu se vraća razlika na karticu', 'Kupljeni obroci se poništavaju', 'Zadržavaju cenu iz trenutka kupovine', 'd', 'Pri kupovini se pamti cena po obroku. Nova cena važi odmah, ali samo za nove kupovine.'),
('Kupovina obroka', 'lako', 'Šta aplikacija radi kada na kartici nema dovoljno novca za kupovinu obroka?', 'Kupi onoliko obroka koliko može', 'Dozvoli da stanje ode u minus', 'Pošalje dug na email studenta', 'Odbija kupovinu i nudi link „Dopuni karticu“', 'd', 'Stanje kartice nikad ne može da bude negativno. To proverava i aplikacija i baza podataka.'),
('Kupovina obroka', 'tesko', 'Danas je 21. u mesecu koji ima 30 dana, a student nema nijedan doručak. Koliko najviše doručaka može da kupi za tekući mesec?', '10', '30', '21', '9', 'a', 'Dozvoljen je jedan doručak dnevno, a od 21. do 30. ostalo je 10 dana, računajući i današnji.'),
('QR bon i kasa', 'lako', 'Gde student pronalazi QR bon koji pokazuje na kasi menze?', 'Na stranici „Moji obroci“', 'Na početnoj stranici', 'U poruci na emailu', 'Odštampan je na studentskoj kartici', 'a', 'Na stranici Moji obroci student bira obrok, a ispod se prikazuje QR bon za taj obrok.'),
('QR bon i kasa', 'srednje', 'Koliko dugo važi jedan QR bon?', '10 sekundi', 'Do kraja dana', 'Do kraja meseca', '2 minuta', 'd', 'Stranica traži novi bon svakog minuta, a kasa prihvata bon koji nije stariji od 2 minuta. Zato snimak ekrana brzo prestaje da važi.'),
('QR bon i kasa', 'tesko', 'Šta sprečava studenta da sam napravi lažni QR bon?', 'QR kod ne može da se kopira', 'Kasir napamet zna sve studente', 'Bon je potpisan tajnim ključem servera, pa bez ključa potpis nije ispravan', 'Ništa, zato bon i ne služi za izdavanje obroka', 'c', 'U bonu su kartica, obrok i vreme nastanka, uz potpis (HMAC-SHA256). Promena bilo kog dela kvari potpis i kasa javlja grešku.'),
('QR bon i kasa', 'srednje', 'Kasir u 10:15 skenira ispravan bon za ručak. Šta kasa javlja?', 'Izdaje ručak', 'Da je bon istekao', 'Da umesto ručka izda doručak', 'Da se ručak izdaje od 11:30 do 15:00', 'd', 'Svaki obrok se izdaje samo u svom radnom vremenu: doručak 07:00–09:30, ručak 11:30–15:00, večera 17:30–20:30.'),
('QR bon i kasa', 'lako', 'Šta kasir radi kada kamera ne može da očita QR bon?', 'Pozove administratora', 'Upiše broj studentske kartice i izabere obrok', 'Izda obrok bez ikakve provere', 'Pošalje studenta da se ponovo prijavi', 'b', 'Ručni unos broja kartice prolazi kroz iste provere kao i QR bon.'),
('QR bon i kasa', 'srednje', 'Student je ručao u Menzi Ekonomski i istog dana pokuša da ruča u Menzi Vita Janjić. Šta se dešava?', 'Dobija ručak, jer je to druga menza', 'Kasa odbija, jer je ručak danas već izdat', 'Ručak mu se naplati dvostruko', 'Dobija ručak, ali bez dezerta', 'b', 'Pravilo „jedan obrok svake vrste dnevno“ važi za sve menze zajedno, a kasa pokazuje i u koliko sati je obrok izdat.'),
('QR bon i kasa', 'tesko', 'Dve kase u istom trenutku skeniraju poslednji ručak istog studenta. Šta se dešava?', 'Obe kase izdaju ručak', 'Obe kase odbiju studenta', 'Samo jedna kasa izda ručak, druga dobija poruku da je već izdat', 'Stanje obroka ode u minus', 'c', 'Izdavanje radi u transakciji baze i zaključava red kartice, pa druga kasa čeka i ponovo proverava podatke.'),
('Jelovnik', 'lako', 'Za koliko menzi aplikacija prikazuje jelovnik?', 'Za jednu', 'Za tri', 'Za dve', 'Za pet', 'b', 'Jelovnik postoji za Menzu Ekonomski, Menzu Vita Janjić i Menzu Treći paviljon.'),
('Jelovnik', 'lako', 'U koliko sati se služi doručak?', 'Od 06:00 do 08:00', 'Od 07:00 do 09:30', 'Od 08:00 do 10:00', 'Od 07:30 do 10:30', 'b', 'Radno vreme svakog obroka piše u jelovniku i pri kupovini. Van tog vremena kasa ne izdaje taj obrok.'),
('Jelovnik', 'srednje', 'Administrator je uneo jelovnik i sačuvao ga kao nacrt. Šta studenti vide?', 'Vide ga sa oznakom „Nacrt“', 'Vide ga samo stanari domova', 'Vide ga tek sledećeg dana', 'Ne vide ga dok ga administrator ne objavi', 'd', 'Nacrt je kod administratora označen kao „U izmeni“. Studenti vide samo objavljena jela.'),
('Jelovnik', 'srednje', 'Kako student može da sačuva nedeljni jelovnik kao PDF?', 'Ne može, PDF pravi samo administrator', 'Jelovnik mu stiže na email', 'Dugmetom „Preuzmi nedeljni jelovnik (PDF)“, pa „Sačuvaj kao PDF“ u prozoru za štampu', 'Mora da napravi snimak ekrana', 'c', 'Za štampu se prikazuje cela nedelja, bez menija i dugmadi.'),
('Jelovnik', 'tesko', 'Šta radi dugme za kopiranje kod unosa jelovnika?', 'Odmah objavljuje isti jelovnik za celu nedelju', 'Kopira jelovnik iz druge menze', 'Pravi rezervnu kopiju baze', 'Kopira jela iz prethodnog dana u izabrani dan, kao nacrt', 'd', 'Kopirani jelovnik ostaje nacrt dok ga administrator ne proveri i ne objavi.'),
('Istorija', 'lako', 'U koja dva formata može da se izveze istorija transakcija?', 'CSV i PDF', 'Word i PowerPoint', 'JPG i PNG', 'XML i JSON', 'a', 'CSV se otvara u Excelu, a PDF se pravi preko prozora za štampu.'),
('Istorija', 'srednje', 'Koji period istorija prikazuje kada student ništa ne izabere?', 'Samo današnje transakcije', 'Poslednjih 7 dana', 'Celu godinu', 'Od prvog dana prošlog meseca do danas', 'd', 'Period i vrsta transakcije mogu da se promene u filteru na vrhu stranice.'),
('Istorija', 'tesko', 'Koje transakcije menjaju stanje kartice?', 'Samo uspešne', 'Sve, bez obzira na status', 'Samo uplate', 'I uplate koje čekaju potvrdu', 'a', 'Odbijene uplate i uplate koje čekaju potvrdu vide se u istoriji, ali ne menjaju stanje kartice.'),
('Smeštaj', 'lako', 'Do kog dana u mesecu je rok za plaćanje stanarine?', 'Do 1.', 'Do 10.', 'Do poslednjeg dana u mesecu', 'Do 20.', 'd', 'Za svaki mesec pravi se zaduženje za stanarinu sa rokom 20. u tom mesecu.'),
('Smeštaj', 'srednje', 'Kako student plaća stanarinu za dom u aplikaciji?', 'Samo na šalteru doma', 'Uplatnicom u pošti', 'Sa stanja studentske kartice', 'Gotovinom kod kasira u menzi', 'c', 'Plaćena stanarina se vidi u istoriji kao transakcija vrste „Smeštaj“.'),
('Smeštaj', 'srednje', 'Gde student odmah posle prijave vidi da li je platio stanarinu za tekući mesec?', 'Samo u istoriji transakcija', 'U jelovniku', 'Na početnoj stranici', 'Nigde, mora da pita na šalteru', 'c', 'Početna prikazuje iznos stanarine za tekući mesec i da li je plaćena ili kasni.'),
('Obaveštenja', 'srednje', 'Ko vidi obaveštenje koje je administrator poslao za jedan dom?', 'Svi studenti', 'Samo kasiri', 'Samo studenti koji imaju aktivan ugovor u tom domu', 'Svi koji jedu u menzi pored doma', 'c', 'Obaveštenja za ceo dom (npr. nestanak vode) ne zatrpavaju studente koji tamo ne žive.'),
('Obaveštenja', 'tesko', 'Ko vidi obaveštenje namenjeno jednoj menzi?', 'Samo studenti koji su danas jeli u toj menzi', 'Svi studenti, jer svako može da jede u bilo kojoj menzi', 'Samo kasiri te menze', 'Samo stanari doma pored te menze', 'b', 'Uz takvo obaveštenje piše naziv menze, pa student zna na koju se odnosi.'),
('Uloge', 'lako', 'Koje uloge imaju zaposleni u aplikaciji?', 'Administrator i kasir', 'Profesor i asistent', 'Kuvar i konobar', 'Direktor i sekretar', 'a', 'Administrator vodi jelovnik, cene, uplate i obaveštenja, a kasir proverava QR bonove i izdaje obroke.'),
('Uloge', 'srednje', 'Kako se prijavljuju zaposleni Studentskog centra?', 'Na posebnoj stranici, korisničkim imenom i lozinkom', 'Isto kao studenti, brojem kartice', 'Ne prijavljuju se, imaju poseban računar', 'Preko Google naloga', 'a', 'Zaposleni imaju posebnu prijavu, a posle nje administrator ide na svoj pregled, kasir na proveru bonova.'),
('Uloge', 'tesko', 'Šta se dešava kada kasir pokuša da otvori stranicu za unos jelovnika?', 'Može da menja jelovnik kao administrator', 'Dobija praznu stranicu sa greškom', 'Automatski se odjavljuje', 'Vraća se na svoju stranicu, proveru bonova', 'd', 'Svaka stranica za zaposlene proverava ulogu, pa kasir vidi samo ono što mu treba na kasi.');
